  -H 'Accept: application/json'
```

### JavaScript

```javascript
const response = await fetch("https://openaliment.ro/api/v2/public/batches/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/recipe-versions", {
  method: "GET",
  credentials: "omit",
  headers: {
  "Accept": "application/json"
}
