  "type": "object",
  "properties": {
    "status": {
      "enum": [
        "operational",
        "unavailable"
      ],
      "description": "Starea moderării: pending, published, restricted sau rejected."
    },
    "checked_at": {
      "type": "string",
      "format": "date-time",
      "example": "2026-10-24T09:00:00+00:00",
      "description": "Moment ISO 8601 cu fus orar explicit; păstrează offset-ul sau convertește explicit la UTC."
    },
    "ai_required": {
      "const": false,
      "description": "false indică faptul că verificarea sau citirea nu necesită un serviciu AI."
    }
  },
  "required": [
